// Parse /tag or /graph commands forwarded from WF-01
const body = $input.item.json.body || $input.item.json;
const text = (body.text || '').trim();
const userId = body.user_id || '';
const channelId = body.channel_id || '';
const threadTs = body.thread_ts || body.ts || '';

// ── /graph command ──
if (text === '/graph' || text.startsWith('/graph ') || text.startsWith('/graph\t')) {
  return {
    json: {
      command: 'graph',
      error: false,
      channel_id: channelId,
      thread_ts: threadTs,
      user_id: userId
    }
  };
}

// ── /tag command ──
const commandRegex = /^\/tag\s+(\S+)\s+(\S+)\s+(.+)$/i;
const match = text.match(commandRegex);

if (!match) {
  return {
    json: {
      command: 'tag',
      error: true,
      channel_id: channelId,
      thread_ts: threadTs,
      message: `:x: *Sintaxis incorrecta.*\n\`/tag <file_name> <field> <valores>\`\n\nEjemplos:\n\`/tag TSW_coherence_protocol narrative_role exploration\`\n\`/tag TSW_coherence_protocol tags filosofia espiral\`\n\`/tag TSW_coherence_protocol entities Ana NEYEN\`\n\n*Campos válidos:* \`narrative_role\` · \`tags\` · \`entities\`\n*Roles válidos:* \`realisation\` · \`exploration\` · \`conflict\` · \`symbol\` · \`system\` · \`orphaned\`\n\nUsa también \`/graph\` para ver el resumen del grafo.`
    }
  };
}

const [, fileName, field, valuesStr] = match;
const values = valuesStr.split(/\s+/).filter(Boolean);

const VALID_FIELDS = ['tags', 'entities', 'narrative_role'];
if (!VALID_FIELDS.includes(field)) {
  return {
    json: {
      command: 'tag',
      error: true,
      channel_id: channelId,
      thread_ts: threadTs,
      message: `:x: Campo inválido: \`${field}\`\n*Campos válidos:* \`narrative_role\` · \`tags\` · \`entities\``
    }
  };
}

const VALID_ROLES = ['realisation','exploration','conflict','symbol','system','orphaned'];
if (field === 'narrative_role' && !VALID_ROLES.includes(values[0])) {
  return {
    json: {
      command: 'tag',
      error: true,
      channel_id: channelId,
      thread_ts: threadTs,
      message: `:x: Rol inválido: \`${values[0]}\`\n*Roles válidos:* \`${VALID_ROLES.join('\` · \`')}\``
    }
  };
}

return {
  json: {
    command: 'tag',
    error: false,
    file_name: fileName,
    field: field,
    values: values,
    channel_id: channelId,
    thread_ts: threadTs,
    user_id: userId
  }
};

// Send error message to Slack via incoming webhook
const d = $input.item.json;
await this.helpers.httpRequest({
  method: 'POST',
  url: '{{ SLACK_WEBHOOK_PLACEHOLDER }}',
  headers: { 'Content-Type': 'application/json' },
  body: { text: d.message },
  json: true
});
return { json: { status: 'error_sent', message: d.message } };

// Call Supabase tag_entry() RPC, then log to audit table
const d = $input.item.json;
if (d.command !== 'tag' || d.error) {
  return { json: d };
}

const ANON = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdzbXR6ZHJhbXF6Y3FkeXdib3JvIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzM0NDg4NTIsImV4cCI6MjA4OTAyNDg1Mn0.0EWXPtw2A9darfVDBgCwyGw0oWGtHdKBokCf2c1Ku24';
const HEADERS = {
  'apikey': ANON,
  'Authorization': 'Bearer ' + ANON,
  'Content-Type': 'application/json'
};

// 1. Apply the tag via tag_entry()
const result = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://gsmtzdramqzcqdywboro.supabase.co/rest/v1/rpc/tag_entry',
  headers: HEADERS,
  body: {
    p_file_name: d.file_name,
    p_field: d.field,
    p_values: d.values
  },
  json: true
});

// 2. Write to audit log (fire-and-forget — never block the /tag response on this)
const crosslinkCount = (result && result.crosslink) ? (result.crosslink.related_count || 0) : 0;
this.helpers.httpRequest({
  method: 'POST',
  url: 'https://gsmtzdramqzcqdywboro.supabase.co/rest/v1/rpc/log_tag_command',
  headers: HEADERS,
  body: {
    p_file_name: d.file_name,
    p_field: d.field,
    p_values: d.values,
    p_slack_user_id: d.user_id || null,
    p_channel_id: d.channel_id || null,
    p_crosslink_count_after: crosslinkCount
  },
  json: true
}).catch(() => {}); // audit failure must not break the /tag response

return {
  json: {
    ...d,
    rpc_result: result
  }
};

// Build confirmation or error Slack message
const d = $input.item.json;
const rpc = d.rpc_result || {};

let msg;
if (rpc.status === 'ok') {
  const fieldEmoji = { tags: ':label:', entities: ':bust_in_silhouette:', narrative_role: ':spiral_note_pad:' };
  const emoji = fieldEmoji[d.field] || ':white_check_mark:';
  const valDisplay = Array.isArray(d.values) ? d.values.map(v => '`' + v + '`').join(' ') : String(d.values);
  const crosslink = rpc.crosslink || {};
  const crosslinkInfo = crosslink.related_count > 0
    ? ` · :link: ${crosslink.related_count} conexiones encontradas`
    : ' · :white_circle: sin conexiones aún';
  msg = `${emoji} *Tag aplicado*\n` +
    `*Entrada:* \`${d.file_name}\`\n` +
    `*Campo:* \`${d.field}\` → ${valDisplay}${crosslinkInfo}\n` +
    `_Crosslink ejecutado automáticamente._`;
} else {
  msg = `:x: *Error al aplicar tag*\n` +
    `\`${d.file_name}\` — ${rpc.message || 'Error desconocido'}`;
}

return {
  json: {
    message: msg,
    channel_id: d.channel_id,
    rpc_ok: rpc.status === 'ok'
  }
};

// Post confirmation to Slack
const d = $input.item.json;
await this.helpers.httpRequest({
  method: 'POST',
  url: '{{ SLACK_WEBHOOK_PLACEHOLDER }}',
  headers: { 'Content-Type': 'application/json' },
  body: { text: d.message },
  json: true
});
return { json: { status: 'ok', message: d.message } };

// Fetch role_distribution() from Supabase
const ANON = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdzbXR6ZHJhbXF6Y3FkeXdib3JvIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzM0NDg4NTIsImV4cCI6MjA4OTAyNDg1Mn0.0EWXPtw2A9darfVDBgCwyGw0oWGtHdKBokCf2c1Ku24';
const result = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://gsmtzdramqzcqdywboro.supabase.co/rest/v1/rpc/role_distribution',
  headers: {
    'apikey': ANON,
    'Authorization': 'Bearer ' + ANON,
    'Content-Type': 'application/json'
  },
  body: {},
  json: true
});
return { json: { ...($input.item.json), stats: result } };

// Build a visual /graph summary for Slack
const d = $input.item.json;
const stats = d.stats || {};
const total = stats.total || 0;
const byRole = stats.by_role || {};
const topTags = stats.top_tags || [];
const orphaned = stats.orphaned_structural || 0;

// Role config: emoji + display name
const ROLE_CONFIG = {
  realisation:   { emoji: ':bulb:',          label: 'Realisation'   },
  exploration:   { emoji: ':mag:',            label: 'Exploration'   },
  conflict:      { emoji: ':zap:',            label: 'Conflict'      },
  symbol:        { emoji: ':cyclone:',        label: 'Symbol'        },
  system:        { emoji: ':gear:',           label: 'System'        },
  orphaned:      { emoji: ':white_circle:',   label: 'Orphaned'      },
  setup:         { emoji: ':triangular_ruler:', label: 'Setup'       },
  integration:   { emoji: ':link:',           label: 'Integration'   },
  inciting_event:{ emoji: ':boom:',           label: 'Inciting event'},
  pilot:         { emoji: ':rocket:',         label: 'Pilot'         },
  unclassified:  { emoji: ':question:',       label: 'Unclassified'  },
};

// Sort roles by count descending
const sorted = Object.entries(byRole).sort((a, b) => b[1] - a[1]);

// Build bar chart lines
const maxCount = sorted[0]?.[1] || 1;
const BAR_WIDTH = 12;
const roleLines = sorted.map(([role, count]) => {
  const cfg = ROLE_CONFIG[role] || { emoji: ':small_blue_diamond:', label: role };
  const pct = Math.round((count / total) * 100);
  const bars = Math.round((count / maxCount) * BAR_WIDTH);
  const bar = '█'.repeat(bars) + '░'.repeat(BAR_WIDTH - bars);
  return `${cfg.emoji} \`${bar}\` *${count}* ${cfg.label} _(${pct}%)_`;
}).join('\n');

// Top tags
const tagLine = topTags.slice(0, 8).map(t => `\`${t.tag}\``).join(' · ');

const msg = `:bar_chart: *NEYEN Knowledge Graph*\n` +
  `_${total} entradas · ${orphaned} huérfanas sin conectar_\n\n` +
  `*Distribución por rol narrativo:*\n${roleLines}\n\n` +
  `*Tags más frecuentes:*\n${tagLine || '—'}\n\n` +
  `_Usa \`/tag <file_name> narrative_role <role>\` para reclasificar._\n` +
  `_Ver grafo completo: <https://neyen.thespiralwithin.ai/graph/|neyen.thespiralwithin.ai/graph>_`;

return {
  json: {
    message: msg,
    channel_id: d.channel_id
  }
};

// Post /graph summary to Slack
const d = $input.item.json;
await this.helpers.httpRequest({
  method: 'POST',
  url: '{{ SLACK_WEBHOOK_PLACEHOLDER }}',
  headers: { 'Content-Type': 'application/json' },
  body: { text: d.message },
  json: true
});
return { json: { status: 'ok', command: 'graph' } };
